bounded_host_request.command:
set -u
output=$(docker exec debug-ai-debug-ai-1 node -e 'const {createAiCoreAdapter}=require("/app/server/adapters/ai-core.js");const e=process.env;const u={coder:e.DEBUG_AI_CORE_GATE_CODER_URL,qwen3:e.DEBUG_AI_CORE_GATE_QWEN3_URL,granite:e.DEBUG_AI_CORE_GATE_GRANITE_URL,ministral:e.DEBUG_AI_CORE_GATE_MINISTRAL_URL};const codes={AI_CORE_GATE_MODEL_MISMATCH:41,AI_CORE_GATE_UNREACHABLE:40,AI_CORE_GATE_PREFLIGHT_TIMEOUT:43,AI_CORE_GATE_BODY_INVALID:44,AI_CORE_GATE_CONFIG_INVALID:45};try{const a=createAiCoreAdapter({baseUrl:e.DEBUG_AI_CORE_URL,apiKey:e.AI_CORE_API_KEY,modelGateBaseUrls:u,dispatchMode:"model_gates"});a.preflightConfiguredGates({probeTimeoutMs:2500}).then(()=>process.exit(0)).catch(x=>process.exit(x.code==="AI_CORE_GATE_HTTP"?(({401:31,429:32,503:33})[x.meta?.status]||34):(codes[x.code]||49)))}catch(x){process.exit(codes[x.code]||48)}' 2>&1)
rc=$?
if [ "$rc" -ne 1 ]; then exit "$rc"; fi
if [ -z "$output" ]; then exit 60; fi
case "$output" in
  *SyntaxError*) exit 61 ;;
  *MODULE_NOT_FOUND*|*"Cannot find module"*) exit 62 ;;
  *TypeError*) exit 63 ;;
  *ReferenceError*) exit 64 ;;
  *EACCES*|*PermissionError*) exit 65 ;;
  *Error*) exit 66 ;;
  *) exit 69 ;;
esac
